// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title CrossChainGovernanceRelay
 * @notice Relays governance proposals signed by council members using bitmap-based nonce tracking
 * @dev Uses sliding window nonce bitmaps for gas-efficient replay protection
 */
contract CrossChainGovernanceRelay is Ownable {
    using ECDSA for bytes32;

    struct Proposal {
        address signer;
        uint256 nonce;
        bytes32 actionHash;
        uint256 deadline;
        uint8 quorumWeight;
    }

    // Council members with their voting weights
    mapping(address => uint8) public councilWeight;
    address[] public councilMembers;

    // Bitmap-based nonce tracking: mapping(signer => mapping(wordIndex => bitmap))
    // Each bit in the bitmap represents whether a nonce has been used
    mapping(address => mapping(uint256 => uint256)) private nonceBitmaps;

    // Executed proposals
    mapping(bytes32 => bool) public executed;

    // Current governance state
    bytes32 public currentActionRoot;
    uint256 public totalWeight;
    uint256 public requiredWeight;

    event ProposalExecuted(bytes32 indexed proposalHash, address indexed signer, uint256 nonce);
    event CouncilMemberAdded(address indexed member, uint8 weight);
    event CouncilMemberRemoved(address indexed member);

    constructor(uint256 _requiredWeight) {
        requiredWeight = _requiredWeight;
    }

    function addCouncilMember(address member, uint8 weight) external onlyOwner {
        require(member != address(0), "Zero address");
        require(councilWeight[member] == 0, "Already member");
        require(weight > 0 && weight <= 100, "Invalid weight");
        councilWeight[member] = weight;
        councilMembers.push(member);
        totalWeight += weight;
        emit CouncilMemberAdded(member, weight);
    }

    function removeCouncilMember(address member) external onlyOwner {
        require(councilWeight[member] > 0, "Not a member");
        totalWeight -= councilWeight[member];
        councilWeight[member] = 0;
        emit CouncilMemberRemoved(member);
    }

    /**
     * @notice Check if a nonce has been used for a given signer
     * @param signer The signer address
     * @param nonce The nonce to check
     * @return True if the nonce has been used
     */
    function isNonceUsed(address signer, uint256 nonce) public view returns (bool) {
        uint256 wordIndex = nonce / 256;
        uint256 bitIndex = nonce % 256;
        uint256 word = nonceBitmaps[signer][wordIndex];
        uint256 mask = 1 << bitIndex;
        return (word & mask) != 0;
    }

    /**
     * @notice Mark a nonce as used. Uses unchecked arithmetic for gas optimization
     *         on the bit manipulation since we've already validated bounds.
     * @param signer The signer address  
     * @param nonce The nonce to invalidate
     */
    function _useNonce(address signer, uint256 nonce) internal {
        uint256 wordIndex = nonce / 256;
        uint256 bitIndex = nonce % 256;
        uint256 word = nonceBitmaps[signer][wordIndex];
        uint256 mask = 1 << bitIndex;
        require((word & mask) == 0, "Nonce already used");
        // Gas optimization: use unchecked for bitmap OR since overflow is impossible
        // on a single-bit set operation
        unchecked {
            nonceBitmaps[signer][wordIndex] = word | mask;
        }
    }

    /**
     * @notice Invalidate a range of nonces for the caller (for key rotation)
     * @param startNonce The starting nonce (must be word-aligned, i.e., multiple of 256)
     * @param count Number of 256-bit words to invalidate
     */
    function invalidateNonces(uint256 startNonce, uint256 count) external {
        require(councilWeight[msg.sender] > 0, "Not a council member");
        // startNonce must be word-aligned
        uint256 wordStart = startNonce / 256;
        for (uint256 i = 0; i < count; i++) {
            nonceBitmaps[msg.sender][wordStart + i] = type(uint256).max;
        }
    }

    /**
     * @notice Compute the EIP-712-style message hash for a proposal
     */
    function _computeProposalHash(Proposal calldata proposal) internal view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("Proposal(address signer,uint256 nonce,bytes32 actionHash,uint256 deadline,uint8 quorumWeight)"),
                proposal.signer,
                proposal.nonce,
                proposal.actionHash,
                proposal.deadline,
                proposal.quorumWeight,
                block.chainid,
                address(this)
            )
        );
    }

    /**
     * @notice Execute a governance proposal with a valid council signature
     * @param proposal The proposal struct
     * @param signature The ECDSA signature from the council member
     */
    function executeProposal(Proposal calldata proposal, bytes calldata signature) external {
        // Deadline check
        require(block.timestamp <= proposal.deadline, "Proposal expired");
        require(proposal.deadline <= block.timestamp + 7 days, "Deadline too far");

        // Compute and verify hash
        bytes32 proposalHash = _computeProposalHash(proposal);
        require(!executed[proposalHash], "Already executed");

        // Recover signer from signature
        bytes32 ethSignedHash = proposalHash.toEthSignedMessageHash();
        (address recoveredSigner, ECDSA.RecoverError err) = ethSignedHash.tryRecover(signature);
        require(err == ECDSA.RecoverError.NoError, "Invalid signature");
        require(recoveredSigner != address(0), "Zero address recovery");

        // Verify signer matches proposal and is authorized
        require(recoveredSigner == proposal.signer, "Signer mismatch");
        require(councilWeight[recoveredSigner] > 0, "Not authorized");
        require(proposal.quorumWeight <= councilWeight[recoveredSigner], "Weight exceeds allowance");

        // Verify nonce hasn't been used
        _useNonce(recoveredSigner, proposal.nonce);

        // Mark as executed and apply
        executed[proposalHash] = true;
        currentActionRoot = proposal.actionHash;

        emit ProposalExecuted(proposalHash, recoveredSigner, proposal.nonce);
    }

    /**
     * @notice Execute multiple proposals in batch for gas efficiency
     * @dev Proposals from the same signer can use sequential nonces in one tx
     */
    function batchExecuteProposals(
        Proposal[] calldata proposals,
        bytes[] calldata signatures
    ) external {
        require(proposals.length == signatures.length, "Length mismatch");
        require(proposals.length <= 32, "Batch too large");

        uint256 accumulatedWeight = 0;

        for (uint256 i = 0; i < proposals.length; i++) {
            Proposal calldata proposal = proposals[i];

            // Deadline check
            if (block.timestamp > proposal.deadline) continue;
            if (proposal.deadline > block.timestamp + 7 days) continue;

            // Compute hash
            bytes32 proposalHash = _computeProposalHash(proposal);
            if (executed[proposalHash]) continue;

            // Recover and verify signer
            bytes32 ethSignedHash = proposalHash.toEthSignedMessageHash();
            (address recoveredSigner, ECDSA.RecoverError err) = ethSignedHash.tryRecover(signatures[i]);
            if (err != ECDSA.RecoverError.NoError) continue;
            if (recoveredSigner == address(0)) continue;
            if (recoveredSigner != proposal.signer) continue;
            if (councilWeight[recoveredSigner] == 0) continue;
            if (proposal.quorumWeight > councilWeight[recoveredSigner]) continue;

            // Check nonce - here we use a different validation for batch efficiency
            uint256 wordIndex = proposal.nonce >> 8; // equivalent to / 256
            uint256 bitIndex = proposal.nonce & 0xFF; // equivalent to % 256
            uint256 word = nonceBitmaps[recoveredSigner][wordIndex];

            // Skip if nonce already used
            if ((word & (1 << bitIndex)) != 0) continue;

            // Mark nonce as used - gas optimized inline version
            nonceBitmaps[recoveredSigner][wordIndex] = word | (1 << bitIndex);

            // Mark executed and accumulate weight
            executed[proposalHash] = true;
            accumulatedWeight += proposal.quorumWeight;
            currentActionRoot = proposal.actionHash;

            emit ProposalExecuted(proposalHash, recoveredSigner, proposal.nonce);
        }
    }

    /**
     * @notice Emergency: owner can invalidate a proposal hash directly
     */
    function emergencyInvalidate(bytes32 proposalHash) external onlyOwner {
        executed[proposalHash] = true;
    }

    /**
     * @notice Get the next available nonce for a signer (scans forward)
     * @param signer The signer to check
     * @param startFrom Nonce to start scanning from
     */
    function getNextNonce(address signer, uint256 startFrom) external view returns (uint256) {
        for (uint256 i = startFrom; i < startFrom + 256; i++) {
            if (!isNonceUsed(signer, i)) return i;
        }
        revert("No available nonce in range");
    }
}
